7	/**
8	 * Formatovani ceny – STARA verze. Bere koruny (ne halere!) a vzdy pridava Kč.
9	 * @deprecated pouzivej format_price()
10	 */
11	function cena($kc)
12	{
13	    return number_format((float) $kc, 0, ',', '.') . ',- Kč';
14	}
15	
16	/**
17	 * @deprecated pouzivej format_date()
18	 */
19	function datum($d)
20	{
21	    if (!$d) {
22	        return '';
23	    }
24	
25	    return date('d.m.Y', strtotime((string) $d));
26	}
27	
28	/**
29	 * Soucet objednavky v halerich, BEZ slevy, v mene objednavky.
30	 */
31	function order_total($orderId)
32	{
33	    global $db;
34	    legacy_db();
35	    $row = $db->one("SELECT SUM(quantity * unit_price_amount_in_cents) AS total FROM order_items WHERE order_id = '" . $orderId . "'");
36	    if ($row === null || $row['total'] === null) {
37	        return 0;
38	    }
39	
40	    return (int) $row['total'];
41	}
42	
43	/**
44	 * Soucet objednavky vcetne slevy. (Pridano 2017 kvuli fakturam.)
45	 */
46	function order_total_after_discount($orderId)
47	{
48	    global $db;
49	    legacy_db();
50	    $total = order_total($orderId);
51	    $o = $db->one("SELECT discount_amount_in_cents FROM orders WHERE id = '" . $orderId . "'");
52	    if ($o) {
53	        $total = $total - (int) $o['discount_amount_in_cents'];
54	    }
55	    if ($total < 0) {
56	        $total = 0;
57	    }
58	
59	    return $total;
60	}
61	
62	function customer_name($customerId)
63	{
64	    static $cache = array();
65	    if (isset($cache[$customerId])) {
66	        return $cache[$customerId];
67	    }
68	    global $db;
69	    legacy_db();
70	    $c = $db->one("SELECT name, email FROM customers WHERE id = '" . $customerId . "'");
71	    if ($c === null) {
72	        // zakaznik z noveho e-shopu, ktery jeste neni v customers
73	        $cache[$customerId] = '(neznámý zákazník)';
74	    } else {
75	        $cache[$customerId] = $c['name'] != '' ? $c['name'] : $c['email'];
76	    }
77	
78	    return $cache[$customerId];
79	}
80	
81	function product_name($productId)
82	{
83	    static $cache = array();
84	    if (isset($cache[$productId])) {
85	        return $cache[$productId];
86	    }
87	    global $db;
88	    legacy_db();
89	    $p = $db->one("SELECT name FROM products WHERE id = '" . $productId . "'");
90	    $cache[$productId] = $p ? $p['name'] : '(smazaný produkt)';
91	
92	    return $cache[$productId];
93	}
