95	/**
96	 * Zapis do auditniho logu.
97	 */
98	function audit_log($entity, $entityId, $action, $payload = array())
99	{
100	    global $db;
101	    legacy_db();
102	    $user = isset($_SESSION['admin_login']) ? $_SESSION['admin_login'] : 'system';
103	    $payload['user'] = $user;
104	    $db->exec("INSERT INTO audit_log (entity, entity_id, action, payload, created_at) VALUES ("
105	        . $db->quote($entity) . ", "
106	        . $db->quote($entityId) . ", "
107	        . $db->quote($action) . ", "
108	        . $db->quote(json_encode($payload)) . ", "
109	        . "'" . date('Y-m-d H:i:s') . "')");
110	}
111	
112	function array_get($arr, $key, $default = null)
113	{
114	    return is_array($arr) && array_key_exists($key, $arr) ? $arr[$key] : $default;
115	}
116	
117	/**
118	 * Prevod halere -> koruny. Pozor, vraci float.
119	 */
120	function hal2kc($cents)
121	{
122	    return $cents / 100;
123	}
124	
125	function kc2hal($kc)
126	{
127	    // carka -> tecka, mezery pryc ("1 200,50" -> 1200.50)
128	    $kc = str_replace(array(' ', ','), array('', '.'), (string) $kc);
129	
130	    return (int) round(((float) $kc) * 100);
131	}
132	
133	/**
134	 * Mena objednavky.
135	 */
136	function order_currency($orderId)
137	{
138	    $o = db_one("SELECT currency FROM orders WHERE id = '" . $orderId . "'");
139	
140	    return $o ? $o['currency'] : 'CZK';
141	}
142	
143	/**
144	 * Pocet objednavek ve stavu. Pouziva dashboard.
145	 */
146	function count_orders($state = null)
147	{
148	    $sql = "SELECT COUNT(*) AS c FROM orders";
149	    if ($state !== null) {
150	        $sql .= " WHERE status = '" . $state . "'";
151	    }
152	    $r = db_one($sql);
153	
154	    return $r ? (int) $r['c'] : 0;
155	}
156	
157	/**
158	 * Stare overeni emailu.
159	 */
160	function is_email($email)
161	{
162	    return filter_var((string) $email, FILTER_VALIDATE_EMAIL) !== false;
163	}
164	
165	// FIXME: nikde se nepouziva? (martin 2018)
166	function generate_password($len = 8)
167	{
168	    $chars = 'abcdefghjkmnpqrstuvwxyz23456789';
169	    $pw = '';
170	    for ($i = 0; $i < $len; $i++) {
171	        $pw .= $chars[random_int(0, strlen($chars) - 1)];
172	    }
173	
174	    return $pw;
175	}
