177	/**
178	 * Seznam ID z checkboxu -> kus SQL "'a','b','c'"
179	 * (escapuje jen apostrofy, viz db_escape_old)
180	 */
181	function ids_to_sql($ids)
182	{
183	    $out = array();
184	    foreach ((array) $ids as $id) {
185	        $out[] = "'" . db_escape_old($id) . "'";
186	    }
187	
188	    return implode(',', $out);
189	}
