191	/**
192	 * Prikaz pro novy e-shop (src/Ordering). Vraci vysledek handleru.
193	 * Most pripravi $GLOBALS['LEGACY_COMMAND'] (viz Http/LegacyFrontController).
194	 */
195	function legacy_command($command)
196	{
197	    if (!isset($GLOBALS['LEGACY_COMMAND']) || !is_callable($GLOBALS['LEGACY_COMMAND'])) {
198	        throw new \RuntimeException('Příkazy nového e-shopu jdou volat jen přes /admin/legacy');
199	    }
200	
201	    return call_user_func($GLOBALS['LEGACY_COMMAND'], $command);
202	}
